import XCTest
@testable import Detour

/// Replays content/drill-test-vectors.json, which is generated by the web app's drill code.
final class DrillTests: XCTestCase {
    private struct Vectors: Decodable {
        struct Round: Decodable {
            struct Problem: Decodable {
                let prompt: String
                let answer: Double
                let choices: [String]?
            }
            let track: String
            let level: Int
            let seed: UInt32
            let problems: [Problem]
        }
        struct Number: Decodable {
            let input: String
            let value: Double?
        }
        let rounds: [Round]
        let numbers: [Number]
    }

    private func loadVectors() throws -> Vectors {
        let url = try XCTUnwrap(Bundle(for: DrillTests.self).url(forResource: "drill-test-vectors", withExtension: "json"), "drill vectors not bundled")
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    func testRoundsMatchTheWebGenerator() throws {
        let vectors = try loadVectors()
        XCTAssertFalse(vectors.rounds.isEmpty)
        for round in vectors.rounds {
            let spec = DrillSpec(track: TrackId(rawValue: round.track)!, level: round.level, seed: round.seed)
            let mine = Drills.generateRound(spec)
            let label = "\(round.track) level \(round.level) seed \(round.seed)"
            XCTAssertEqual(mine.map { $0.prompt }, round.problems.map { $0.prompt }, label)
            for (a, b) in zip(mine, round.problems) {
                XCTAssertEqual(a.answer, b.answer, accuracy: 1e-9, "\(label): \(a.prompt)")
                XCTAssertEqual(a.choices ?? [], b.choices ?? [], "\(label): \(a.prompt)")
            }
        }
    }

    func testNumberParsingMatchesTheWeb() throws {
        for n in try loadVectors().numbers {
            let parsed = Drills.parseNumber(n.input)
            if let expected = n.value {
                XCTAssertEqual(try XCTUnwrap(parsed, "'\(n.input)' should parse"), expected, accuracy: 1e-9, n.input)
            } else {
                XCTAssertNil(parsed, "'\(n.input)' should not parse")
            }
        }
    }

    func testJudging() {
        let p = DrillProblem(prompt: "2 + 2", answer: 4, hint: nil)
        XCTAssertTrue(Drills.judge(.mentalMath, p, input: "4").correct)
        XCTAssertFalse(Drills.judge(.mentalMath, p, input: "5").correct)
        let e = DrillProblem(prompt: "?", answer: 1000, hint: nil)
        XCTAssertTrue(Drills.judge(.estimation, e, input: "1800").correct)
        XCTAssertFalse(Drills.judge(.estimation, e, input: "300").correct)
        XCTAssertFalse(Drills.judge(.estimation, e, input: "lots").correct)
    }

    func testLevelingNeedsTwentyAttemptsAtEightyPercent() {
        func results(_ right: Int, _ total: Int) -> [Bool] { (0..<total).map { $0 < right } }
        XCTAssertFalse(Skills.shouldLevelUp(results(16, 19)))
        XCTAssertFalse(Skills.shouldLevelUp(results(15, 20)))
        XCTAssertTrue(Skills.shouldLevelUp(results(16, 20)))

        var p = SkillProgress(track: .mentalMath)
        var leveledUp = false
        for round in 0..<7 {
            (p, leveledUp) = Skills.apply(p, results: [true, true, true], now: Date(timeIntervalSince1970: Double(round)))
        }
        XCTAssertEqual(p.level, 2)
        XCTAssertEqual(p.attemptsTotal, 21)
        XCTAssertTrue(p.recentResults.isEmpty)
        XCTAssertTrue(leveledUp)
    }

    func testTracksAlternateLeastRecentFirst() {
        XCTAssertEqual(Skills.nextTrack([]), .mentalMath)
        var m = SkillProgress(track: .mentalMath); m.lastAt = Date(timeIntervalSince1970: 10)
        var e = SkillProgress(track: .estimation); e.lastAt = Date(timeIntervalSince1970: 20)
        var g = SkillProgress(track: .algebra); g.lastAt = Date(timeIntervalSince1970: 30)
        XCTAssertEqual(Skills.nextTrack([m, e, g], among: [.mentalMath, .estimation, .algebra]), .mentalMath)
        XCTAssertEqual(Skills.nextTrack([m, e, g]), .geometry, "never practised, first in the list")
        XCTAssertEqual(Skills.nextTrack([m, e, g], among: [.estimation, .algebra]), .estimation)
        XCTAssertEqual(Skills.nextTrack([m]), .algebra, "never-practised tracks come first, in the same order as the web app")
    }

    func testScoring() {
        XCTAssertEqual(Scoring.timesOff(100, 100), 1, accuracy: 1e-12)
        XCTAssertEqual(Scoring.timesOff(50, 100), 2, accuracy: 1e-9)
        XCTAssertEqual(Scoring.estimationVerdict(105, 100), "Spot on")
        XCTAssertEqual(Scoring.closeness(guess: 71, answer: 71, lo: 0, hi: 100, scale: "linear"), 1)
        XCTAssertEqual(Scoring.closeness(guess: 0, answer: 100, lo: 0, hi: 100, scale: "linear"), 0)
        // $1 at 10% for 50 years is about $117 on a 1...100,000 slider; 5,000 is ~43x too big, not "in the ballpark".
        XCTAssertTrue(Scoring.closenessLabel(Scoring.closeness(guess: 5000, answer: 117, lo: 1, hi: 100_000, scale: "log")).hasPrefix("Not quite"))
        XCTAssertEqual(Scoring.closenessLabel(Scoring.closeness(guess: 100, answer: 117, lo: 1, hi: 100_000, scale: "log")), "Very close")
        XCTAssertEqual(Scoring.closenessLabel(Scoring.closeness(guess: 200, answer: 117, lo: 1, hi: 100_000, scale: "log")), "In the ballpark")
    }

    func testEveryLevelGivesWholeAnswersAndWellFormedOptions() {
        var withOptions = 0
        for track in TrackId.allCases where track != .estimation && track != .mentalMath {
            for level in 1...Drills.info(track).maxLevel {
                for seed in UInt32(1)...UInt32(25) {
                    for p in Drills.generateRound(DrillSpec(track: track, level: level, seed: seed, count: 3)) {
                        let label = "\(track.rawValue) \(level): \(p.prompt)"
                        XCTAssertEqual(p.answer, p.answer.rounded(), label)
                        XCTAssertGreaterThanOrEqual(p.answer, 0, label)
                        if let options = p.choices {
                            withOptions += 1
                            XCTAssertTrue((2...4).contains(options.count), label)
                            XCTAssertEqual(Set(options).count, options.count, label)
                            XCTAssertLessThan(Int(p.answer), options.count, label)
                        }
                    }
                }
            }
        }
        XCTAssertGreaterThan(withOptions, 100)
    }

    func testSkillsHaveTheLevelsTheWebHas() {
        for track in [TrackId.algebra, .geometry, .probability, .numberTheory, .money, .fractions, .sequences, .rates] {
            XCTAssertEqual(Drills.info(track).maxLevel, 20, track.rawValue)
            XCTAssertEqual(Set(Drills.info(track).levels).count, 20, track.rawValue)
        }
        XCTAssertEqual(Drills.info(.statistics).maxLevel, 24)
    }

    func testAMultipleChoiceAnswerIsJudgedByItsIndex() {
        let p = DrillProblem(prompt: "Is 7 prime?", answer: 0, hint: nil, choices: ["Prime", "Not prime"])
        XCTAssertTrue(Drills.judge(.numberTheory, p, input: "0").correct)
        XCTAssertFalse(Drills.judge(.numberTheory, p, input: "1").correct)
    }

    func testEstimationAsksForTheClosestBallpark() {
        for level in 1...Drills.info(.estimation).maxLevel {
            for seed in UInt32(1)...UInt32(60) {
                for p in Drills.generateRound(DrillSpec(track: .estimation, level: level, seed: seed)) {
                    let options = p.choices ?? []
                    XCTAssertEqual(options.count, 4, p.prompt)
                    XCTAssertEqual(Set(options).count, 4, p.prompt)
                    XCTAssertLessThan(Int(p.answer), 4, p.prompt)
                    for label in options {
                        XCTAssertNotNil(label.range(of: #"^\d+(\.\d)?( thousand| million| billion)?$"#, options: .regularExpression), label)
                    }
                    // The hint shows the product; the right option is that product in two digits.
                    let terms = (p.hint ?? "").components(separatedBy: " is about ")[0].components(separatedBy: " × ").compactMap { Int($0) }
                    let product = terms.reduce(1, *)
                    XCTAssertEqual(options[Int(p.answer)], Drills.inWords(Drills.twoDigits(product)), p.prompt)
                }
            }
        }
    }

    func testRoundingToTwoDigitsAndSayingItInWords() {
        XCTAssertEqual(Drills.twoDigits(912_500), 910_000)
        XCTAssertEqual(Drills.twoDigits(99), 99)
        XCTAssertEqual(Drills.twoDigits(1_450), 1_500)
        XCTAssertEqual(Drills.inWords(910_000), "910 thousand")
        XCTAssertEqual(Drills.inWords(1_500_000), "1.5 million")
        XCTAssertEqual(Drills.inWords(12_000_000), "12 million")
        XCTAssertEqual(Drills.inWords(2_600_000_000), "2.6 billion")
        XCTAssertEqual(Drills.inWords(840), "840")
    }
}
